value:
$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class NrMappedModule {
 [DllImport("kernel32.dll", SetLastError=true)]
 public static extern IntPtr OpenProcess(uint access, bool inherit, uint pid);
 [DllImport("kernel32.dll", SetLastError=true)]
 public static extern bool CloseHandle(IntPtr handle);
 [DllImport("psapi.dll", CharSet=CharSet.Unicode, SetLastError=true)]
 public static extern uint GetMappedFileName(IntPtr process, IntPtr address, StringBuilder name, uint size);
 [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
 public static extern uint QueryDosDevice(string device, StringBuilder target, uint size);
}
'@
$gameProcess = Get-Process -Id 28724
$processHandle = [NrMappedModule]::OpenProcess(0x410, $false, 28724)
if ($processHandle -eq [IntPtr]::Zero) { throw "OpenProcess failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
$device = New-Object System.Text.StringBuilder 2048
[void][NrMappedModule]::QueryDosDevice('D:', $device, 2048)
$items = foreach ($module in $gameProcess.Modules | Where-Object ModuleName -in @('CommunityShaders.dll','devbench.dll')) {
 $mapped = New-Object System.Text.StringBuilder 32768
 $length = [NrMappedModule]::GetMappedFileName($processHandle, $module.BaseAddress, $mapped, 32768)
 if (!$length) { throw "GetMappedFileName failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
 $physical = $mapped.ToString()
 if ($physical.StartsWith($device.ToString(), [StringComparison]::OrdinalIgnoreCase)) { $physical = 'D:' + $physical.Substring($device.Length) }
 $item = Get-Item -LiteralPath $physical
 [pscustomobject]@{module=$module.ModuleName; reportedPath=$module.FileName; mappedPath=$mapped.ToString(); physicalPath=$physical; bytes=$item.Length; sha256=(Get-FileHash -LiteralPath $physical -Algorithm SHA256).Hash; pid=$gameProcess.Id; processStartUtc=$gameProcess.StartTime.ToUniversalTime().ToString('o')}
}
$items | ConvertTo-Json -Depth 8
[void][NrMappedModule]::CloseHandle($processHandle)
